begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into public.canvases(id,owner_id,title) values ('88888888-8888-4888-8888-888888888888','10000000-0000-4000-8000-000000000001','Voice comment guard QA');
select is((select enabled from public.canvas_ai_settings where canvas_id='88888888-8888-4888-8888-888888888888'),true,'new canvas enables AI');
select is((select authority::text from public.canvas_ai_settings where canvas_id='88888888-8888-4888-8888-888888888888'),'trusted_editor','new canvas defaults to Trusted Editor');
set local role service_role;
select public.reserve_live_voice_test('99999999-9999-4999-8999-999999999999','88888888-8888-4888-8888-888888888888','10000000-0000-4000-8000-000000000001');
update public.voice_test_sessions set supervisor_ready=true,heartbeat_at=now() where id='99999999-9999-4999-8999-999999999999';
select public.reserve_voice_delegation('99999999-9999-4999-8999-999999999999','comment-qa');
select set_config('test.voice_task_id',(select id::text from public.voice_delegations where delegation_id='comment-qa'),true);
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.create_comment_thread(target_canvas_id=>'88888888-8888-4888-8888-888888888888',target_client_command_id=>current_setting('test.voice_task_id')::uuid,target_body=>'Leave a comment on the shape.',target_anchor_x=>0,target_anchor_y=>0,target_object_ids=>array[]::uuid[],target_ordered_context_ids=>array[]::uuid[],target_include_primary_ai=>true);
reset role;
update public.voice_delegations d set ai_run_id=r.id from public.ai_runs r where r.idempotency_key=d.id and d.delegation_id='comment-qa';
update public.ai_runs set status='thinking' where idempotency_key=(select id from public.voice_delegations where delegation_id='comment-qa');
set local role service_role;
select lives_ok($$select public.execute_ai_contextual_comment((select ai_run_id from public.voice_delegations where delegation_id='comment-qa'),'10000000-0000-4000-8000-000000000001','comment-one','A verified contextual comment.',array['aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa']::uuid[],0)$$,'active metered voice owner can leave a contextual comment');
select lives_ok($$select public.execute_ai_contextual_comment((select ai_run_id from public.voice_delegations where delegation_id='comment-qa'),'10000000-0000-4000-8000-000000000001','comment-one','A verified contextual comment.',array['aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa']::uuid[],0)$$,'replayed call is idempotent');
reset role;
select is((select count(*) from public.comments where canvas_id='88888888-8888-4888-8888-888888888888' and author_kind='ai'),1::bigint,'one contextual comment persisted');
set local role service_role;
update public.voice_test_sessions set backend_cancel_at=clock_timestamp() where id='99999999-9999-4999-8999-999999999999';
select throws_ok($$select public.execute_ai_contextual_comment((select ai_run_id from public.voice_delegations where delegation_id='comment-qa'),'10000000-0000-4000-8000-000000000001','comment-cancelled','Must not persist.',array['aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa']::uuid[],0)$$,'42501',null,'cancellation blocks tool write atomically');
update public.voice_test_sessions set backend_cancel_at=null,close_requested_at=now() where id='99999999-9999-4999-8999-999999999999';
select throws_ok($$select public.execute_ai_contextual_comment((select ai_run_id from public.voice_delegations where delegation_id='comment-qa'),'10000000-0000-4000-8000-000000000001','comment-closed','Must not persist.',array['aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa']::uuid[],0)$$,'42501',null,'closing blocks late tool write');
reset role;
select is((select count(*) from public.comments where canvas_id='88888888-8888-4888-8888-888888888888' and author_kind='ai'),1::bigint,'blocked actions leave no comments');
reset role;
select * from finish();
rollback;
